  1→import { useState } from "react";
  2→import { Badge } from "@/components/ui/badge";
  3→import { GraduationCap, BookOpen, School, Award, ChevronDown, ChevronUp, AlertTriangle } from "lucide-react";
  4→import { Button } from "@/components/ui/button";
  5→
  6→interface Education {
  7→  degree?: string;
  8→  institution?: string;
  9→  year?: string;
 10→}
 11→
 12→interface EducationPanelProps {
 13→  parsedJson: any;
 14→  matchedMustHaves?: string[];
 15→  missingMustHaves?: string[];
 16→}
 17→
 18→/* ── Helpers ──────────────────────────────────────────────── */
 19→
 20→/** Extract the most recent 4-digit year from a date string */
 21→const extractYear = (yearStr?: string | number): number | null => {
 22→  if (yearStr == null) return null;
 23→  if (typeof yearStr === "number") return yearStr >= 1900 && yearStr <= 2100 ? yearStr : null;
 24→  const match = String(yearStr).match(/\b(19|20)\d{2}\b/g);
 25→  if (!match) return null;
 26→  return Math.max(...match.map(Number));
 27→};
 28→
 29→/** Year pill colour: green if recent (≤3 yrs), amber if old (5+ yrs), grey otherwise */
 30→const getYearVariant = (year: number): { cls: string } => {
 31→  const age = new Date().getFullYear() - year;
 32→  if (age <= 3) return { cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
 33→  if (age >= 5) return { cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
 34→  return { cls: "bg-muted text-muted-foreground border-border" };
 35→};
 36→
 37→/** Infer education level from degree name for icon + rank */
 38→type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";
 39→
 40→const inferLevel = (degree: string): EduLevel => {
 41→  const d = degree.toLowerCase();
 42→  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
 43→  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
 44→  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
 45→  // Check secondary/higher_secondary BEFORE diploma — "High School Diploma" should be secondary, not diploma
 46→  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
 47→  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
 48→  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd") || d.includes("post graduate diploma")) return "diploma";
 49→  return "other";
 50→};
 51→
 52→const LEVEL_ICON: Record<EduLevel, typeof GraduationCap> = {
 53→  doctorate: Award,
 54→  masters: GraduationCap,
 55→  bachelors: BookOpen,
 56→  diploma: School,
 57→  higher_secondary: School,
 58→  secondary: School,
 59→  other: GraduationCap,
 60→};
 61→
 62→const LEVEL_RANK: Record<EduLevel, { label: string; cls: string }> = {
 63→  doctorate: { label: "Research", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" },
 64→  masters: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
 65→  bachelors: { label: "Ranked", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" },
 66→  diploma: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
 67→  higher_secondary: { label: "Tier 2", cls: "bg-muted text-muted-foreground border-border" },
 68→  secondary: { label: "Secondary", cls: "bg-muted text-muted-foreground border-border" },
 69→  other: { label: "Other", cls: "bg-muted text-muted-foreground border-border" },
 70→};
 71→
 72→/** Is this a low-relevance qualification? (secondary school etc.) */
 73→const isLowRelevance = (level: EduLevel): boolean =>
 74→  level === "secondary" || level === "higher_secondary";
 75→
 76→/** Match score label */
 77→const getScoreLabel = (score: number): { text: string; cls: string } => {
 78→  if (score >= 75) return { text: "Strong", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
 79→  if (score >= 50) return { text: "Good", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
 80→  if (score >= 25) return { text: "Partial", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
 81→  return { text: "Weak", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
 82→};
 83→
 84→type RelevanceTag = "jd_match" | "relevant" | "gap" | "low_relevance";
 85→const RELEVANCE_CLS: Record<RelevanceTag, string> = {
 86→  jd_match: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800",
 87→  relevant: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800",
 88→  gap: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800",
 89→  low_relevance: "bg-muted/60 text-muted-foreground border-border",
 90→};
 91→const RELEVANCE_LABEL: Record<RelevanceTag, string> = {
 92→  jd_match: "JD Match",
 93→  relevant: "Relevant",
 94→  gap: "Gap",
 95→  low_relevance: "Low relevance",
 96→};
 97→
 98→/* ── Component ────────────────────────────────────────────── */
 99→
100→const EducationPanel = ({ parsedJson, matchedMustHaves, missingMustHaves }: EducationPanelProps) => {
101→  const [showDetail, setShowDetail] = useState(false);
102→  const education: Education[] = parsedJson?.education || [];
103→  const certifications: string[] = parsedJson?.certifications || [];
104→  const matchedLower = (matchedMustHaves || []).map((m: string) => m.toLowerCase());
105→  const missingLower = (missingMustHaves || []).map((m: string) => m.toLowerCase());
106→
107→  // Classify each education entry
108→  const classified = education.map((edu) => {
109→    const degree = edu.degree || "";
110→    const institution = edu.institution || "";
111→    const combined = `${degree} ${institution}`.toLowerCase();
112→    const level = inferLevel(degree);
113→    const year = extractYear(edu.year);
114→    const Icon = LEVEL_ICON[level];
115→    const rank = LEVEL_RANK[level];
116→
117→    let tag: RelevanceTag = isLowRelevance(level) ? "low_relevance" : "relevant";
118→    const isMatched = matchedLower.some((m) => {
119→      const words = m.split(/\s+/).filter((w) => w.length > 3);
120→      return words.some((w) => combined.includes(w));
121→    });
122→    if (isMatched) tag = "jd_match";
123→
124→    return { ...edu, degree, institution, level, year, Icon, rank, tag };
125→  });
126→
127→  // Stats
128→  const jdMatchCount = classified.filter((c) => c.tag === "jd_match").length;
129→  const relevantCount = classified.filter((c) => c.tag === "relevant").length;
130→  const useful = classified.filter((c) => c.tag !== "low_relevance");
131→
132→  // Education gaps — missing must-haves related to education
133→  const educationKeywords = ["degree", "education", "qualification", "certified", "certificate", "diploma", "bachelor", "master", "phd", "analytics", "marketing", "design", "engineering", "computer", "science", "mba"];
134→  const educationGaps = missingLower
135→    .filter((m) => educationKeywords.some((k) => m.includes(k)) || m.includes("formal"))
136→    .map((m) => {
137→      const original = (missingMustHaves || []).find((o) => o.toLowerCase() === m) || m;
138→      const isCritical = matchedLower.length > 0 || missingLower.indexOf(m) < missingLower.length / 2;
139→      return { text: original, severity: isCritical ? "critical" as const : "preferred" as const };
140→    });
141→  const gapCount = educationGaps.length;
142→
143→  // Match score: percentage of useful qualifications vs total, weighted by relevance
144→  const matchScore = classified.length > 0
145→    ? Math.round((useful.length / classified.length) * (jdMatchCount > 0 ? 90 : 65) + (jdMatchCount > 0 ? 10 : 0))
146→    : 0;
147→  const scoreLabel = getScoreLabel(matchScore);
148→
149→  return (
150→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
151→      {/* ── Header with stat pills ─────────────────────────── */}
152→      <div className="flex items-center gap-2 flex-wrap">
153→        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
154→          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
155→        </div>
156→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
157→        <div className="flex items-center gap-1 ml-auto flex-wrap">
158→          {jdMatchCount > 0 && (
159→            <Badge variant="outline" className={`text-[9px] ${RELEVANCE_CLS.jd_match}`}>
160→              {jdMatchCount} JD Match
161→            </Badge>
162→          )}
163→          {relevantCount > 0 && (
164→            <Badge variant="outline" className={`text-[9px] ${RELEVANCE_CLS.relevant}`}>
165→              {relevantCount} Relevant
166→            </Badge>
167→          )}
168→          {gapCount > 0 && (
169→            <Badge variant="outline" className={`text-[9px] ${RELEVANCE_CLS.gap}`}>
170→              {gapCount} Gap
171→            </Badge>
172→          )}
173→        </div>
174→      </div>
175→
176→      {/* ── Match score bar ────────────────────────────────── */}
177→      {classified.length > 0 && (
178→        <div className="space-y-1.5">
179→          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Education Match Score</span>
180→          <div className="flex items-center gap-3">
181→            <span className="text-xl font-bold tabular-nums text-foreground">{matchScore}%</span>
182→            <div className="flex-1 space-y-1">
183→              <div className="flex items-center gap-1.5">
184→                <Badge variant="outline" className={`text-[9px] ${scoreLabel.cls}`}>{scoreLabel.text}</Badge>
185→                <span className="text-[9px] text-muted-foreground">AI estimated · {useful.length} of {classified.length} useful</span>
186→              </div>
187→              <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
188→                <div
189→                  className="h-full rounded-full bg-score-education transition-all"
190→                  style={{ width: `${Math.min(matchScore, 100)}%` }}
191→                />
192→              </div>
193→              <div className="flex justify-between text-[8px] text-muted-foreground/50">
194→                <span>Weak</span><span>Partial</span><span>Good</span><span>Strong</span>
195→              </div>
196→            </div>
197→          </div>
198→        </div>
199→      )}
200→
201→      {/* ── Qualifications list ────────────────────────────── */}
202→      {classified.length > 0 ? (
203→        <div className="space-y-1">
204→          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Qualifications</span>
205→          <div className="space-y-2">
206→            {classified.slice(0, 4).map((edu, i) => {
207→              const lowRel = edu.tag === "low_relevance";
208→              return (
209→                <div key={i} className={`flex items-start gap-2 ${lowRel ? "opacity-40" : ""}`}>
210→                  <edu.Icon className={`h-3.5 w-3.5 shrink-0 mt-0.5 ${lowRel ? "text-muted-foreground/60" : "text-muted-foreground"}`} />
211→                  <div className="flex-1 min-w-0 space-y-0.5">
212→                    <p className={`text-xs font-medium leading-tight ${lowRel ? "text-muted-foreground" : "text-foreground"}`}>
213→                      {edu.degree || "Degree"}
214→                    </p>
215→                    {edu.institution && (
216→                      <p className="text-[11px] text-muted-foreground">{edu.institution}</p>
217→                    )}
218→                    <div className="flex items-center gap-1.5 flex-wrap">
219→                      {edu.year && edu.year !== "" && (() => {
220→                        const yearNum = edu.year ? extractYear(edu.year) : null;
221→                        const yearVariant = yearNum ? getYearVariant(yearNum) : null;
222→                        return (
223→                          <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${yearVariant?.cls || "bg-muted text-muted-foreground border-border"}`}>
224→                            {yearNum || edu.year}
225→                          </span>
226→                        );
227→                      })()}
228→                      {!lowRel && (
229→                        <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${edu.rank.cls}`}>
230→                          {edu.rank.label}
231→                        </span>
232→                      )}
233→                    </div>
234→                  </div>
235→                  <Badge variant="outline" className={`text-[9px] shrink-0 mt-0.5 ${RELEVANCE_CLS[edu.tag]}`}>
236→                    {RELEVANCE_LABEL[edu.tag]}
237→                  </Badge>
238→                </div>
239→              );
240→            })}
241→            {classified.length > 4 && (
242→              <p className="text-[10px] text-muted-foreground">+{classified.length - 4} more</p>
243→            )}
244→          </div>
245→        </div>
246→      ) : (
247→        <p className="text-xs text-muted-foreground">No education data available</p>
248→      )}
249→
250→      {/* ── Gaps — Hiring Risk ─────────────────────────────── */}
251→      {educationGaps.length > 0 && (
252→        <div className="space-y-1.5">
253→          <span className="text-[10px] uppercase tracking-wider text-destructive font-medium flex items-center gap-1">
254→            <AlertTriangle className="h-3 w-3" /> Gaps — Hiring Risk
255→          </span>
256→          <div className="space-y-1.5">
257→            {educationGaps.map((gap, i) => (
258→              <div
259→                key={i}
260→                className={`text-[11px] px-2.5 py-1.5 rounded-md border flex items-center justify-between gap-2 ${
261→                  gap.severity === "critical"
262→                    ? "bg-red-500/10 text-red-700 border-red-200 dark:text-red-400 dark:border-red-800"
263→                    : "bg-amber-500/10 text-amber-700 border-amber-200 dark:text-amber-400 dark:border-amber-800"
264→                }`}
265→              >
266→                <span className="font-medium">{gap.text}</span>
267→                <Badge variant="outline" className={`text-[8px] shrink-0 uppercase ${
268→                  gap.severity === "critical"
269→                    ? "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800"
270→                    : "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800"
271→                }`}>
272→                  {gap.severity}
273→                </Badge>
274→              </div>
275→            ))}
276→          </div>
277→        </div>
278→      )}
279→
280→      {/* ── Footer: certifications + detail toggle ─────────── */}
281→      {(certifications.length > 0 || classified.length > 0) && (
282→        <div className="flex items-center justify-between pt-1 border-t border-border">
283→          <span className="text-[10px] text-muted-foreground">
284→            {certifications.length > 0
285→              ? `${certifications.length} cert${certifications.length !== 1 ? "s" : ""} available`
286→              : "No certifications"}
287→          </span>
288→          {(certifications.length > 0) && (
289→            <Button
290→              variant="ghost"
291→              size="sm"
292→              className="h-6 px-2 text-[10px] text-muted-foreground hover:text-foreground gap-1"
293→              onClick={() => setShowDetail(!showDetail)}
294→            >
295→              See full detail {showDetail ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
296→            </Button>
297→          )}
298→        </div>
299→      )}
300→
301→      {/* ── Expanded certifications ────────────────────────── */}
302→      {showDetail && certifications.length > 0 && (
303→        <div className="space-y-1">
304→          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Certifications</span>
305→          <div className="flex flex-wrap gap-1">
306→            {certifications.map((cert, i) => (
307→              <Badge key={i} variant="outline" className="text-[10px]">{cert}</Badge>
308→            ))}
309→          </div>
310→        </div>
311→      )}
312→    </div>
313→  );
314→};
315→
316→export default EducationPanel;
