  1→import { Badge } from "@/components/ui/badge";
  2→import { Button } from "@/components/ui/button";
  3→import {
  4→  CheckCircle2, XCircle, FileCheck, Lightbulb,
  5→  ShieldCheck, ShieldAlert, Wand2, Target, AlertCircle,
  6→} from "lucide-react";
  7→import type { Result } from "@/pages/Index";
  8→
  9→interface JDAlignedPanelProps {
 10→  result: Result;
 11→  onRewriteJd?: () => void;
 12→}
 13→
 14→/* ── Helpers ──────────────────────────────────────────────── */
 15→
 16→type ColorVariant = "green" | "blue" | "amber" | "red";
 17→
 18→/** Semantic badge classes with dark-mode support */
 19→const VARIANT_CLS: Record<ColorVariant, string> = {
 20→  green: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800",
 21→  blue:  "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800",
 22→  amber: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800",
 23→  red:   "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800",
 24→};
 25→
 26→const PILL_CLS: Record<ColorVariant, string> = {
 27→  green: "bg-emerald-500/10 text-emerald-700 border-emerald-200 dark:text-emerald-300 dark:border-emerald-800",
 28→  blue:  "bg-blue-500/10 text-blue-700 border-blue-200 dark:text-blue-300 dark:border-blue-800",
 29→  amber: "bg-amber-500/10 text-amber-700 border-amber-200 dark:text-amber-300 dark:border-amber-800",
 30→  red:   "bg-red-500/10 text-red-700 border-red-200 dark:text-red-300 dark:border-red-800",
 31→};
 32→
 33→const getMatchLabel = (score: number): { text: string; v: ColorVariant } => {
 34→  if (score >= 70) return { text: "Strong match", v: "green" };
 35→  if (score >= 50) return { text: "Good match",   v: "blue" };
 36→  if (score >= 30) return { text: "Partial match", v: "amber" };
 37→  return { text: "Weak match", v: "red" };
 38→};
 39→
 40→const getConfidenceLabel = (c: number): { text: string; v: ColorVariant } => {
 41→  if (c >= 70) return { text: "High confidence",   v: "green" };
 42→  if (c >= 40) return { text: "Medium confidence", v: "amber" };
 43→  return { text: "Low confidence", v: "red" };
 44→};
 45→
 46→const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; v: ColorVariant } => {
 47→  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", v: "amber" };
 48→  if (score >= 70 && hardFit !== false)
 49→    return { text: "Shortlist — strong core fit, gaps are learnable", v: "green" };
 50→  if (score >= 50 && hardFit !== false)
 51→    return { text: "Consider — decent match, review before interview", v: "blue" };
 52→  if (score >= 40)
 53→    return { text: "Review — has strengths but missing critical items", v: "amber" };
 54→  return { text: "Pass — significant gaps for this role", v: "red" };
 55→};
 56→
 57→/* ── Component ────────────────────────────────────────────── */
 58→
 59→const JDAlignedPanel = ({ result: r, onRewriteJd }: JDAlignedPanelProps) => {
 60→  const matched = (r.matched_must_haves as string[]) || [];
 61→  const missing = (r.missing_must_haves as string[]) || [];
 62→  const strengths = (r.strengths_json || []) as string[];
 63→  const gaps = (r.gaps_json || []) as string[];
 64→  const confidence = r.confidence ?? 0;
 65→  const interviewQs = Array.isArray(r.interview_questions) ? (r.interview_questions as string[]) : [];
 66→  const isHeuristic = r.scoring_version === "heuristic";
 67→  const isInsufficient = r.scoring_version === "insufficient";
 68→
 69→  // Don't render for insufficient data — nothing meaningful to show
 70→  if (isInsufficient) return null;
 71→
 72→  // Must-have stats
 73→  const totalMustHave = matched.length + missing.length;
 74→  const mustHavePercent = totalMustHave > 0 ? Math.round((matched.length / totalMustHave) * 100) : 0;
 75→
 76→  // Preferred: use stored GPT data when available, fallback to derivation
 77→  // For heuristic results, matched_must_haves and strengths overlap — skip derivation
 78→  const matchedPreferred: string[] =
 79→    r.explanation_json?.matched_preferred ??
 80→    (isHeuristic ? [] : strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))).slice(0, 5));
 81→  const missingPreferred: string[] =
 82→    r.explanation_json?.missing_preferred ??
 83→    (isHeuristic ? [] : gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))).slice(0, 3));
 84→  const totalPreferred = matchedPreferred.length + missingPreferred.length;
 85→
 86→  // Risk signals — positive first (anchoring bias: lead with good news)
 87→  const risks: { text: string; v: ColorVariant }[] = [];
 88→  // Positives first
 89→  if (matched.length === totalMustHave && totalMustHave > 0)
 90→    risks.push({ text: "All must-haves met", v: "green" });
 91→  if (confidence >= 70) risks.push({ text: "High confidence score", v: "green" });
 92→  // Warnings
 93→  if (confidence >= 40 && confidence < 70) risks.push({ text: "Medium confidence", v: "amber" });
 94→  if (isHeuristic) risks.push({ text: "Quick scoring only", v: "amber" });
 95→  // Negatives last — only show gaps NOT already in the Must Have column
 96→  if (confidence > 0 && confidence < 40) risks.push({ text: "Low confidence score", v: "red" });
 97→  if (r.hard_fit === false && missing.length > 0) risks.push({ text: "Missing critical requirements", v: "red" });
 98→
 99→  const matchLabel = getMatchLabel(r.overall_score);
100→  const confLabel = getConfidenceLabel(confidence);
101→  const rec = getRecommendation(r.overall_score, r.hard_fit, isHeuristic);
102→
103→  // Don't render if there's truly nothing to show
104→  if (totalMustHave === 0 && totalPreferred === 0 && !r.explanation_json?.why_ranked_here && risks.length === 0) return null;
105→
106→  return (
107→    <div className="rounded-lg border border-border bg-card overflow-hidden">
108→      {/* ── Header ─────────────────────────────────────────── */}
109→      <div className="px-4 py-3 border-b border-border bg-muted/30">
110→        <div className="flex items-center gap-3 flex-wrap">
