 17→
 18→/** Extract a 4-digit year from any date string format */
 19→const extractYear = (dateStr?: string): number | null => {
 20→  if (!dateStr) return null;
 21→  const match = dateStr.match(/\b(19|20)\d{2}\b/);
 22→  return match ? parseInt(match[0]) : null;
 23→};
 24→
 25→/** Check if a date string indicates "current/present" role */
 26→const isCurrent = (dateStr?: string): boolean => {
 27→  if (!dateStr) return false;
 28→  const lower = dateStr.toLowerCase().trim();
 29→  return lower === "current" || lower === "present" || lower === "now" || lower.includes("present") || lower.includes("current");
 30→};
 31→
 32→/** Compute duration in years between two date strings */
 33→const computeYears = (start?: string, end?: string): number => {
 34→  const startYear = extractYear(start);
 35→  if (!startYear) return 0;
 36→  const endYear = isCurrent(end) ? new Date().getFullYear() : extractYear(end);
 37→  if (!endYear) {
 38→    // If end is missing, try extracting a range from start string (e.g., "2021 – 2025")
 39→    const rangeMatch = start?.match(/\b((?:19|20)\d{2})\b.*\b((?:19|20)\d{2})\b/);
 40→    if (rangeMatch) {
 41→      return Math.max(0, parseInt(rangeMatch[2]) - parseInt(rangeMatch[1]));
 42→    }
 43→    return 0;
 44→  }
 45→  return Math.max(0, endYear - startYear);
 46→};
 47→
 48→const ExperiencePanel = ({ parsedJson }: ExperiencePanelProps) => {
 49→  const roles: Role[] = parsedJson?.roles_with_dates || parsedJson?.experience || [];
 50→
 51→  const totalYears = roles.length > 0
 52→    ? roles.reduce((sum, r) => sum + computeYears(r.start, r.end), 0)
 53→    : null;
 54→
 55→  return (
 56→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
 57→      <div className="flex items-center gap-2 mb-1">
 58→        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
