 60→        </div>
 61→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
 62→        {totalYears !== null && totalYears > 0 && (
 63→          <Badge variant="outline" className="ml-auto text-[10px]">{totalYears} yrs</Badge>
 64→        )}
 65→      </div>
 66→
 67→      {roles.length > 0 ? (
