 69→          {roles.slice(0, 4).map((role, i) => {
 70→            const startYear = extractYear(role.start);
 71→            const endYear = isCurrent(role.end) ? "Present" : extractYear(role.end);
 72→            const duration = startYear && endYear ? `${startYear} – ${endYear}` : role.start || "";
 73→            const years = computeYears(role.start, role.end);
 74→            const isCurrentRole = isCurrent(role.end);
 75→            const empType = role.employment_type || role.type;
 76→
 77→            return (
