 96→                    )}
 97→                  </div>
 98→                </div>
 99→              </div>
100→            );
101→          })}
102→          {roles.length > 4 && (
103→            <p className="text-[10px] text-muted-foreground">+{roles.length - 4} more roles</p>
104→          )}
105→        </div>
